101: fn sleep_until_poll(deadline: Instant, poll_index: &mut usize) {
102:     let remaining = deadline.saturating_duration_since(Instant::now());
103:     if remaining.is_zero() {
104:         return;
105:     }
106:     thread::sleep(adaptive_poll_delay(*poll_index).min(remaining));
107:     *poll_index = poll_index.saturating_add(1);
108: }
